package fi.hospitalos.handsfree
import org.junit.Test
import org.junit.Assert.*

class DictationTest {
  private var now=1000L
  private val sent=mutableListOf<Pair<String,Action>>()
  private val people=listOf(Colleague("aino","Aino",true),Colleague("ben","Ben",true))
  private fun engine()=HandsFreeEngine("aino",{now}){id,a->sent.add(id to a)}.also{it.connection(true);it.snapshot(people,emptyList());it.bedside.snapshot(listOf(Patient("demo-a","Demo Patient A","enc-a","12")),people,null)}
  private fun identify(e:HandsFreeEngine){e.wake();e.transcript("select patient demo-a");e.reviewDisplayed(e.card.promptId);e.transcript("confirm patient");e.acknowledgement(sent.last().first,true,null,null,PatientContext("demo-a","enc-a",1))}
  @Test fun arbitraryMessageIsReviewedThenPersistedAction(){val e=engine();e.wake();e.transcript("Message Ben");assertEquals("dictating-message",e.card.phase);e.transcript("Do not send the trolley. I will come at 12:00!");assertEquals("Do not send the trolley. I will come at 12:00!",e.card.body);assertTrue(sent.isEmpty());e.transcript("send message");assertTrue(sent.isEmpty());e.reviewDisplayed(e.card.promptId);e.physicalAccept(e.card.promptId);assertEquals("message.send",sent.single().second.type);assertEquals(e.unresolvedCommandId,sent.single().first)}
  @Test fun commandWordsInsideDictationAreContent(){val e=engine();e.wake();e.transcript("message Ben");e.transcript("send message");assertEquals("send message",e.card.body);assertTrue(sent.isEmpty());e.reviewDisplayed(e.card.promptId);e.transcript("send message");assertEquals("send message",sent.single().second.text)}
  @Test fun editMessageInvalidatesFormerReview(){val e=engine();e.wake();e.transcript("tell Ben Come at 12:00.");val old=e.card.promptId;e.reviewDisplayed(old);e.transcript("edit message");e.transcript("Come at 13:00 instead.");e.physicalAccept(old);assertTrue(sent.isEmpty());e.reviewDisplayed(e.card.promptId);e.physicalAccept(e.card.promptId);assertEquals("Come at 13:00 instead.",sent.single().second.text)}
  @Test fun longMessageIsNeverSilentlyTruncated(){val e=engine();e.wake();e.transcript("message Ben");e.transcript("x".repeat(161));assertTrue(sent.isEmpty());assertEquals("Message needs rephrasing",e.card.title)}
  @Test fun notePreservesExactStatementAndNeedsRenderedConfirmation(){val e=engine();identify(e);e.transcript("save to patient records that I gave 400mg of ibuprofen at 12:00.");assertTrue(e.card.body.contains("I gave 400mg of ibuprofen at 12:00."));assertEquals("save note",e.tiltActionLabel);e.transcript("save note");assertTrue(sent.none{it.second.type=="note.save"});e.reviewDisplayed(e.card.promptId);e.physicalAccept(e.card.promptId);val n=sent.last();assertEquals("note.save",n.second.type);assertEquals("I gave 400mg of ibuprofen at 12:00.",n.second.fields["text"]);assertEquals(n.first,e.unresolvedCommandId);e.acknowledgement(n.first,true,null,null);assertEquals("Note saved · synthetic record",e.card.title);assertNull(e.unresolvedCommandId)}
  @Test fun patientIsRequiredAndMissingContextDoesNotRetainNote(){val e=engine();e.wake();e.transcript("add note I gave 400mg at 12:00.");assertEquals("Confirm patient first",e.card.title);assertTrue(sent.none{it.second.type=="note.save"})}
  @Test fun twoTurnNoteAndReplacementRequireNewReview(){val e=engine();identify(e);e.transcript("add patient note");e.transcript("I did not give ibuprofen.");val old=e.card.promptId;e.reviewDisplayed(old);e.transcript("replace note Patient declined the offered medicine.");e.physicalAccept(old);assertTrue(sent.none{it.second.type=="note.save"});e.reviewDisplayed(e.card.promptId);e.transcript("save note");assertEquals("Patient declined the offered medicine.",sent.last().second.fields["text"])}
  @Test fun interruptedNoteSaveReconcilesWithoutReplay(){val e=engine();identify(e);e.transcript("add note Patient asked for water.");e.reviewDisplayed(e.card.promptId);e.transcript("save note");val id=sent.last().first;e.connection(false);assertEquals(id,e.unresolvedCommandId);e.connection(true);assertEquals("command.status",sent.last().second.type);assertEquals(id,sent.last().second.fields["commandId"]);e.reconciled(id,true,null,null);assertNull(e.unresolvedCommandId);assertEquals(1,sent.count{it.second.type=="note.save"})}
  @Test fun contextSwitchAndDismissDiscardUnsubmittedNote(){val e=engine();identify(e);e.transcript("add note Patient asked for water.");val old=e.card.promptId;e.reviewDisplayed(old);e.dismissScreen();e.physicalAccept(old);assertTrue(sent.none{it.second.type=="note.save"})}
  @Test fun speechBufferWaitsForFinalAndQuietGap(){val b=UtteranceBuffer();b.accept("I gave",true,.9f,100);b.accept("400mg of ibuprofen",false,.9f,200);assertFalse(b.complete(2000));b.accept("400mg of ibuprofen at 12:00.",true,.8f,2100);assertFalse(b.complete(2500));assertTrue(b.complete(3000));assertEquals("I gave 400mg of ibuprofen at 12:00.",b.text);assertEquals(.8f,b.confidence)}
  @Test fun cumulativeFinalIsNotDuplicated(){val b=UtteranceBuffer();b.accept("Please bring",true,.9f,1);b.accept("Please bring the trolley.",true,.9f,2);assertEquals("Please bring the trolley.",b.text);b.accept("Please bring the trolley.",true,.9f,3);assertEquals("Please bring the trolley.",b.text)}
  @Test fun overflowAndLowConfidenceDoNotBecomeTruncatedCommands(){val b=UtteranceBuffer();b.accept("x".repeat(201),true,.9f,1);assertTrue(b.overflow);assertFalse(b.complete(5000));assertEquals("",b.text)}
  @Test fun blankFinalCannotCompleteAnUnfinishedPartial(){val b=UtteranceBuffer();b.accept("I gave",true,.9f,1);b.accept("four hundred",false,.9f,2);b.accept("",true,.9f,3);assertFalse(b.complete(3000))}
}
